INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM20IWQPZ', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 3, 'grid_in', E'What is the value of $x$ in the equation $\\frac{5x + 3}{4} - \\frac{2x - 1}{3} = 4$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '5', ARRAY['5'], E'Multiply both sides by $12$, the least common multiple of $4$ and $3$, to clear the fractions: $3(5x + 3) - 4(2x - 1) = 48$. Distribute to get $15x + 9 - 8x + 4 = 48$. Combine like terms: $7x + 13 = 48$. Subtract $13$ from both sides: $7x = 35$. Divide by $7$ to get $x = 5$.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM20PCSQO', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 2, 'mcq', E'Which of the following is equivalent to $\\frac{x^2 - 9}{x^2 + 7x + 12}$?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{x + 3}{x + 4}$"},{"key":"B","text":"$\\frac{x - 3}{x + 4}$"},{"key":"C","text":"$\\frac{x - 3}{x - 4}$"},{"key":"D","text":"$\\frac{x - 9}{x + 12}$"}]$lyceon_json$::jsonb, 'B', NULL, E'Factor the numerator as a difference of squares: $x^2 - 9 = (x - 3)(x + 3)$. Factor the denominator: $x^2 + 7x + 12 = (x + 3)(x + 4)$. Cancel the common factor $(x + 3)$ to get $\\frac{x - 3}{x + 4}$. The expression $\\frac{x + 3}{x + 4}$ incorrectly cancels $(x - 3)$ instead of $(x + 3)$. The expression $\\frac{x - 3}{x - 4}$ uses the wrong sign on the $4$ from factoring the denominator. The expression $\\frac{x - 9}{x + 12}$ incorrectly divides individual terms rather than factoring.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM21XFV00', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 1, 'mcq', E'A recipe calls for $\\frac{7}{4}$ cups of rice to make 14 servings. How many cups of rice are needed to make 22 servings?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{11}{4}$"},{"key":"B","text":"$\\frac{7}{2}$"},{"key":"C","text":"$\\frac{11}{8}$"},{"key":"D","text":"$\\frac{77}{4}$"}]$lyceon_json$::jsonb, 'A', NULL, E'The rate is $\\frac{7}{4} \\div 14 = \\frac{7}{56} = \\frac{1}{8}$ cups per serving. For 22 servings: $22 \\times \\frac{1}{8} = \\frac{22}{8} = \\frac{11}{4}$ cups. The value $\\frac{7}{2}$ results from doubling the original amount rather than using the correct proportion. The value $\\frac{11}{8}$ comes from dividing $\\frac{11}{4}$ by 2, an extra halving step. The value $\\frac{77}{4}$ comes from multiplying $\\frac{7}{4}$ by 11 instead of by the correct scale factor $\\frac{22}{14}$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM22PKAU2', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 2, 'mcq', E'The function $g$ is linear and satisfies $g(2) = 19$ and $g(7) = 54$. What is the rate of change of $g$?', NULL, $lyceon_json$[{"key":"A","text":"$5$"},{"key":"B","text":"$7$"},{"key":"C","text":"$-7$"},{"key":"D","text":"$\\frac{73}{9}$"}]$lyceon_json$::jsonb, 'B', NULL, E'The rate of change (slope) is $\\frac{g(7) - g(2)}{7 - 2} = \\frac{54 - 19}{5} = \\frac{35}{5} = 7$. The value $5$ results from confusing the denominator of the slope formula with the slope itself. The value $-7$ comes from reversing the order of subtraction in the numerator, computing $\\frac{19 - 54}{7 - 2}$, without also reversing the denominator. The value $\\frac{73}{9}$ comes from incorrectly summing the outputs and dividing by the sum of the inputs.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM24863YG', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 2, 'grid_in', E'What is the smallest integer value of $x$ that satisfies the inequality $-4x + 17 < 2x - 31$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '9', ARRAY['9'], E'Solving $-4x + 17 < 2x - 31$: subtract $2x$ from both sides to get $-6x + 17 < -31$. Subtract $17$ from both sides: $-6x < -48$. Divide both sides by $-6$ and reverse the inequality sign: $x > 8$. The smallest integer strictly greater than $8$ is $9$. A common error is forgetting to flip the inequality when dividing by a negative number, which would yield $x < 8$ and the wrong answer of $7$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM25A2KQO', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 3, 'mcq', E'Which expression is equivalent to $\\frac{4x^2 - 25}{2x^2 + 9x + 10} \\cdot \\frac{x^2 + 5x + 6}{2x - 5}$?', NULL, $lyceon_json$[{"key":"A","text":"$x + 3$"},{"key":"B","text":"$x - 3$"},{"key":"C","text":"$\\frac{x + 3}{2x - 5}$"},{"key":"D","text":"$x + 2$"}]$lyceon_json$::jsonb, 'A', NULL, E'Factor each piece: $4x^2 - 25 = (2x - 5)(2x + 5)$. For $2x^2 + 9x + 10$, find factors of $20$ that add to $9$: $4$ and $5$, so $2x^2 + 4x + 5x + 10 = (2x + 5)(x + 2)$. Also $x^2 + 5x + 6 = (x + 2)(x + 3)$. The product becomes $\\frac{(2x - 5)(2x + 5)}{(2x + 5)(x + 2)} \\cdot \\frac{(x + 2)(x + 3)}{2x - 5}$. Cancelling $(2x + 5)$, $(x + 2)$, and $(2x - 5)$ leaves $x + 3$. The expression $x - 3$ uses the wrong sign from the factorization of $x^2 + 5x + 6$. The expression $\\frac{x + 3}{2x - 5}$ fails to cancel the $(2x - 5)$ factors. The expression $x + 2$ confuses which factor remains after cancellation.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM25IPLSV', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 2, 'grid_in', E'A technician charges a flat fee of $\\$23$ for a house call plus $\\$4$ for each quarter-hour of labor. If the total bill for a job is $\\$91$, how many quarter-hours of labor were charged?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '17', ARRAY['17'], E'The total cost is modeled by $C = 23 + 4q$, where $q$ is the number of quarter-hours. Setting $C = 91$ gives $23 + 4q = 91$, so $4q = 68$, and $q = 17$. A common error is forgetting to subtract the flat fee, yielding $91 \\div 4 = 22.75$. Another error is dividing $91$ by $23$, confusing the fee with the per-unit rate.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM25U7TZL', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 2, 'mcq', E'How many distinct real solutions does the equation $2x^2 - 11x + 17 = 0$ have?', NULL, $lyceon_json$[{"key":"A","text":"$0$"},{"key":"B","text":"$1$"},{"key":"C","text":"$2$"},{"key":"D","text":"$4$"}]$lyceon_json$::jsonb, 'A', NULL, E'The discriminant is $b^2 - 4ac = (-11)^2 - 4(2)(17) = 121 - 136 = -15$. Since the discriminant is negative, the equation has $0$ distinct real solutions. The answer $1$ reflects confusing a negative discriminant with a zero discriminant, which would indicate a repeated real root. The answer $2$ assumes every quadratic has two real roots without checking the discriminant. The answer $4$ conflates the number of terms or coefficients with the number of solutions.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM27PI3ZE', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 2, 'grid_in', E'If $y = x^2 + 3x$ and $y = 10x + 18$, what is the positive value of $x$ that satisfies both equations?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '9', ARRAY['9'], E'Setting the two expressions for $y$ equal: $x^2 + 3x = 10x + 18$. Rearranging gives $x^2 - 7x - 18 = 0$. Factoring: $(x - 9)(x + 2) = 0$, so $x = 9$ or $x = -2$. The positive value is $9$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM28BOB9S', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 2, 'mcq', E'A student earns $\\$13$ per hour tutoring and $\\$9$ per hour filing documents. The student must earn at least $\\$390$ per week but can work no more than $35$ hours total. If $t$ represents hours spent tutoring and $d$ represents hours spent filing, which system of inequalities models this situation?', NULL, $lyceon_json$[{"key":"A","text":"$13t + 9d \\geq 390$, $t + d \\leq 35$, $t \\geq 0$, $d \\geq 0$"},{"key":"B","text":"$13t + 9d \\leq 390$, $t + d \\leq 35$, $t \\geq 0$, $d \\geq 0$"},{"key":"C","text":"$13t + 9d \\geq 390$, $t + d \\geq 35$, $t \\geq 0$, $d \\geq 0$"},{"key":"D","text":"$9t + 13d \\geq 390$, $t + d \\leq 35$, $t \\geq 0$, $d \\geq 0$"}]$lyceon_json$::jsonb, 'A', NULL, E'The student earns $\\$13$ per tutoring hour and $\\$9$ per filing hour and needs at least $\\$390$, so $13t + 9d \\geq 390$. The total hours cannot exceed $35$, so $t + d \\leq 35$, with both variables non-negative. The system with $13t + 9d \\leq 390$ reverses the earnings constraint to an upper bound rather than a minimum. The system with $t + d \\geq 35$ requires at least $35$ hours, reversing the maximum-hours constraint. The system with $9t + 13d$ swaps the pay rates between the two activities.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM28UL5GF', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 1, 'mcq', E'A circle has the equation $(x - 7)^2 + (y + 4)^2 = 81$. What is the radius of this circle?', NULL, $lyceon_json$[{"key":"A","text":"$9$"},{"key":"B","text":"$40.5$"},{"key":"C","text":"$81$"},{"key":"D","text":"$\\sqrt{40.5}$"}]$lyceon_json$::jsonb, 'A', NULL, E'The standard form of a circle is $(x - h)^2 + (y - k)^2 = r^2$. Here $r^2 = 81$, so $r = \\sqrt{81} = 9$. The value $40.5$ results from dividing $81$ by $2$ instead of taking the square root. The value $81$ mistakes $r^2$ for $r$. The value $\\sqrt{40.5}$ results from first dividing by $2$ and then taking the square root.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 40, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM29TZL9H', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 2, 'mcq', E'Which expression is equivalent to $(3x - 7)(2x + 9)$?', NULL, $lyceon_json$[{"key":"A","text":"$6x^2 + 13x - 63$"},{"key":"B","text":"$6x^2 - 13x - 63$"},{"key":"C","text":"$6x^2 + 13x + 63$"},{"key":"D","text":"$6x^2 + 41x - 63$"}]$lyceon_json$::jsonb, 'A', NULL, E'Using FOIL: $(3x)(2x) = 6x^2$, $(3x)(9) = 27x$, $(-7)(2x) = -14x$, $(-7)(9) = -63$. Combining: $6x^2 + 27x - 14x - 63 = 6x^2 + 13x - 63$. The expression $6x^2 - 13x - 63$ incorrectly negates the middle term, as if both cross terms were subtracted. The expression $6x^2 + 13x + 63$ incorrectly makes the constant positive, missing the sign from $(-7)(9)$. The expression $6x^2 + 41x - 63$ incorrectly adds the cross terms as $27 + 14 = 41$ instead of $27 - 14 = 13$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2A3X07X', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 3, 'mcq', E'The system of equations $6x + ky = 18$ and $-9x + 12y = -27$ has infinitely many solutions. What is the value of $k$?', NULL, $lyceon_json$[{"key":"A","text":"$-8$"},{"key":"B","text":"$8$"},{"key":"C","text":"$-18$"},{"key":"D","text":"$18$"}]$lyceon_json$::jsonb, 'A', NULL, E'For the system to have infinitely many solutions, the equations must be proportional. The ratio of the $x$-coefficients is $\\frac{6}{-9} = -\\frac{2}{3}$, and the ratio of the constants is $\\frac{18}{-27} = -\\frac{2}{3}$, confirming proportionality. Setting the $y$-coefficient ratio equal: $\\frac{k}{12} = -\\frac{2}{3}$, so $k = 12 \\cdot \\left(-\\frac{2}{3}\\right) = -8$. Verification: multiplying $6x - 8y = 18$ by $-\\frac{3}{2}$ yields $-9x + 12y = -27$, confirming the equations are proportional. The value $8$ results from dropping the negative sign in the ratio. The value $-18$ results from using an incorrect ratio such as $\\frac{6}{-9} \\cdot 27$ instead of the coefficient comparison. The value $18$ combines both a sign error and an incorrect setup.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2B6GBYP', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 2, 'grid_in', E'If $3x + 4y = 43$ and $x + 2y = 19$, what is the value of $y$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '7', ARRAY['7'], E'From the second equation, $x = 19 - 2y$. Substituting into the first equation: $3(19 - 2y) + 4y = 43$, which gives $57 - 6y + 4y = 43$, so $-2y = -14$ and $y = 7$. To verify, $x = 19 - 2(7) = 5$. Checking: $3(5) + 4(7) = 15 + 28 = 43$ and $5 + 2(7) = 19$, both correct. A common error is solving for $x$ instead of $y$, giving $5$. Another error is a sign mistake when distributing, leading to $57 + 6y + 4y = 43$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2B9P1JV', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 3, 'grid_in', E'In the system $y = 3x^2 + bx + 1$ and $y = x - 2$, the graphs are tangent (intersect at exactly one point). What is the positive value of $b$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '7', ARRAY['7'], E'Setting the equations equal: $3x^2 + bx + 1 = x - 2$, which gives $3x^2 + (b - 1)x + 3 = 0$. For the system to have exactly one solution, the discriminant must equal zero: $(b - 1)^2 - 4(3)(3) = 0$, so $(b - 1)^2 = 36$, giving $b - 1 = \\pm 6$. Therefore $b = 7$ or $b = -5$. The positive value is $7$.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2BGWA6B', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 1, 'mcq', E'A laptop originally priced at $\\$1{,}240$ is marked down to $\\$930$. What is the percent decrease in price, rounded to the nearest tenth?', NULL, $lyceon_json$[{"key":"A","text":"$25.0\\%$"},{"key":"B","text":"$33.3\\%$"},{"key":"C","text":"$75.0\\%$"},{"key":"D","text":"$31.0\\%$"}]$lyceon_json$::jsonb, 'A', NULL, E'The decrease is $1240 - 930 = 310$. The percent decrease is $\\frac{310}{1240} \\times 100 = 25.0\\%$. The value $33.3\\%$ comes from dividing 310 by 930 (the sale price) instead of 1240 (the original price). The value $75.0\\%$ represents the fraction of the original price that remains, not the decrease. The value $31.0\\%$ results from a rounding or arithmetic error in the division.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 50, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2C0VSAI', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 3, 'mcq', E'In triangle $ABC$, $AB = 10$, $BC = 21$, and point $D$ lies on $\\overline{BC}$ such that $\\overline{AD} \\perp \\overline{BC}$. If $AD = 8$ and $BD < DC$, what is the length of $AC$?', NULL, $lyceon_json$[{"key":"A","text":"14"},{"key":"B","text":"17"},{"key":"C","text":"23"},{"key":"D","text":"$\\sqrt{505}$"}]$lyceon_json$::jsonb, 'B', NULL, E'Since $AD \\perp BC$, triangle $ABD$ is a right triangle with hypotenuse $AB = 10$ and leg $AD = 8$. By the Pythagorean theorem, $BD = \\sqrt{10^2 - 8^2} = \\sqrt{100 - 64} = \\sqrt{36} = 6$. Since $BD < DC$ and $BD + DC = 21$, we get $DC = 21 - 6 = 15$. Now triangle $ADC$ is a right triangle with legs $AD = 8$ and $DC = 15$, so $AC = \\sqrt{8^2 + 15^2} = \\sqrt{64 + 225} = \\sqrt{289} = 17$. The value $14$ results from adding $BD + AD = 6 + 8$ instead of applying the Pythagorean theorem to triangle $ADC$. The value $23$ results from adding $AD + DC = 8 + 15$ instead of using the Pythagorean theorem. The value $\\sqrt{505}$ results from using $DC = 21$ without subtracting $BD$, giving $\\sqrt{64 + 441}$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 110, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2CI4DWP', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 1, 'mcq', E'A quadratic function has a vertex at $(3, -5)$ and opens upward. Which of the following could be the function?', NULL, $lyceon_json$[{"key":"A","text":"$f(x) = -2(x - 3)^2 - 5$"},{"key":"B","text":"$f(x) = 4(x + 3)^2 - 5$"},{"key":"C","text":"$f(x) = 2(x - 3)^2 - 5$"},{"key":"D","text":"$f(x) = 2(x - 3)^2 + 5$"}]$lyceon_json$::jsonb, 'C', NULL, E'A quadratic with vertex $(h, k) = (3, -5)$ that opens upward has the form $f(x) = a(x - 3)^2 - 5$ where $a > 0$. The expression $2(x - 3)^2 - 5$ satisfies both conditions. The expression $-2(x - 3)^2 - 5$ has the correct vertex but opens downward because $a = -2 < 0$. The expression $4(x + 3)^2 - 5$ shifts the vertex to $(-3, -5)$ due to the $(x + 3)$ term. The expression $2(x - 3)^2 + 5$ places the vertex at $(3, 5)$ instead of $(3, -5)$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2COPCST', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 1, 'mcq', E'In triangle $PQR$, angle $P$ measures $47°$ and angle $Q$ measures $68°$. What is the measure, in degrees, of angle $R$?', NULL, $lyceon_json$[{"key":"A","text":"55"},{"key":"B","text":"65"},{"key":"C","text":"75"},{"key":"D","text":"85"}]$lyceon_json$::jsonb, 'B', NULL, E'The sum of the interior angles of a triangle is $180°$. Therefore, angle $R = 180° - 47° - 68° = 65°$. The value $55°$ results from subtracting $47°$ and $78°$ instead of $68°$. The value $75°$ results from an arithmetic slip when subtracting. The value $85°$ results from subtracting only one angle from $180°$ and then misreading the problem.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2DNPQW9', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 2, 'mcq', E'A right circular cylinder has a radius of $7$ cm and a height of $13$ cm. A second right circular cylinder has a radius of $7$ cm and a height of $39$ cm. The volume of the second cylinder is how many times the volume of the first cylinder?', NULL, $lyceon_json$[{"key":"A","text":"$2$"},{"key":"B","text":"$3$"},{"key":"C","text":"$9$"},{"key":"D","text":"$27$"}]$lyceon_json$::jsonb, 'B', NULL, E'The volume of a cylinder is $V = \\pi r^2 h$. Since both cylinders have the same radius, the ratio of their volumes is $\\frac{\\pi (7)^2 (39)}{\\pi (7)^2 (13)} = \\frac{39}{13} = 3$. The volume of the second cylinder is $3$ times the volume of the first. The value $2$ results from miscalculating the height ratio. The value $9$ comes from squaring the ratio $3^2 = 9$, confusing height scaling with radius scaling. The value $27$ comes from cubing the ratio, as if all dimensions were tripled.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2EV4VQ3', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 2, 'mcq', E'In a class of 40 students, 18 play soccer, 14 play basketball, and 5 play both soccer and basketball. If a student is selected at random from those who play soccer, what is the probability that the student also plays basketball?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{5}{40}$"},{"key":"B","text":"$\\frac{5}{18}$"},{"key":"C","text":"$\\frac{5}{14}$"},{"key":"D","text":"$\\frac{14}{40}$"}]$lyceon_json$::jsonb, 'B', NULL, E'This is a conditional probability question: $P(\\text{basketball} \\mid \\text{soccer})$. Of the 18 soccer players, 5 also play basketball. So the probability is $\\frac{5}{18}$. The value $\\frac{5}{40}$ incorrectly uses the total class size as the denominator instead of the number of soccer players. The value $\\frac{5}{14}$ incorrectly conditions on basketball players instead of soccer players. The value $\\frac{14}{40}$ gives the probability of randomly selecting any basketball player from the whole class, ignoring the condition entirely.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2FMAEFF', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 1, 'mcq', E'What is the slope of the line $7x - 3y = 21$?', NULL, $lyceon_json$[{"key":"A","text":"$-\\frac{7}{3}$"},{"key":"B","text":"$\\frac{7}{3}$"},{"key":"C","text":"$3$"},{"key":"D","text":"$7$"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct answer is $\\frac{7}{3}$. Rewrite $7x - 3y = 21$ in slope-intercept form by solving for $y$: subtract $7x$ from both sides to get $-3y = -7x + 21$, then divide every term by $-3$ to get $y = \\frac{7}{3}x - 7$. The slope is $\\frac{7}{3}$. The value $-\\frac{7}{3}$ results from a sign error when dividing by $-3$. The value $3$ comes from reading the coefficient of $y$ in the original equation rather than computing the slope. The value $7$ comes from taking the coefficient of $x$ in the original equation without converting to slope-intercept form.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2G5L7WI', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 2, 'mcq', E'A researcher finds that the line of best fit for a data set relating the number of hours of sunlight per day ($x$) to the height of a plant in centimeters ($y$) is $y = 2.7x + 4.1$. What does the slope of this line represent in context?', NULL, $lyceon_json$[{"key":"A","text":"The estimated height of the plant with zero hours of sunlight"},{"key":"B","text":"The estimated increase in height, in centimeters, for each additional hour of sunlight per day"},{"key":"C","text":"The estimated total height, in centimeters, after $2.7$ hours of sunlight per day"},{"key":"D","text":"The estimated number of hours of sunlight needed for the plant to grow $1$ centimeter"}]$lyceon_json$::jsonb, 'B', NULL, E'In the equation $y = 2.7x + 4.1$, the slope is $2.7$. The slope of a line of best fit represents the predicted change in the dependent variable ($y$, plant height in centimeters) for each one-unit increase in the independent variable ($x$, hours of sunlight per day). So $2.7$ represents the estimated increase in height of $2.7$ centimeters for each additional hour of sunlight per day. The value $4.1$ (the $y$-intercept) represents the estimated height with zero hours of sunlight, not the slope. Interpreting $2.7$ as a total height after $2.7$ hours confuses the slope with an input value. Interpreting the slope as the number of hours needed per centimeter inverts the relationship; that would be $\\frac{1}{2.7}$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2HOZZB5', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 2, 'mcq', E'What is the value of $x$ if $4(3x + 7) = 2(5x - 3)$?', NULL, $lyceon_json$[{"key":"A","text":"$-34$"},{"key":"B","text":"$-17$"},{"key":"C","text":"$-11$"},{"key":"D","text":"$17$"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct answer is $-17$. Distribute on both sides: $12x + 28 = 10x - 6$. Subtract $10x$ from both sides to get $2x + 28 = -6$. Subtract $28$ from both sides to get $2x = -34$. Divide by $2$ to get $x = -17$. The value $-34$ is the intermediate result before dividing by $2$. The value $-11$ comes from incorrectly distributing $2(5x - 3)$ as $10x + 6$ instead of $10x - 6$, which leads to $2x = -22$ and $x = -11$. The value $17$ results from a sign error in the final step.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2HTFMMR', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 1, 'mcq', E'Which expression is equivalent to $14m^3 - 21m^2 + 7m$?', NULL, $lyceon_json$[{"key":"A","text":"$7(2m^3 - 3m^2 + m)$"},{"key":"B","text":"$7m(2m^2 + 3m + 1)$"},{"key":"C","text":"$7m(2m^2 - 3m + 1)$"},{"key":"D","text":"$7m(2m^2 - 3m - 1)$"}]$lyceon_json$::jsonb, 'C', NULL, E'Each term has a common factor of $7m$: $14m^3 \\div 7m = 2m^2$, $-21m^2 \\div 7m = -3m$, and $7m \\div 7m = 1$. So the expression factors as $7m(2m^2 - 3m + 1)$. The expression $7(2m^3 - 3m^2 + m)$ factors out only $7$ instead of the full GCF of $7m$. The expression $7m(2m^2 + 3m + 1)$ incorrectly makes the $-3m$ term positive. The expression $7m(2m^2 - 3m - 1)$ incorrectly makes the constant term negative.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2IU86AV', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 1, 'mcq', E'A linear function $f$ is defined by $f(x) = 7x - 11$. What is the value of $f(3)$?', NULL, $lyceon_json$[{"key":"A","text":"$10$"},{"key":"B","text":"$-32$"},{"key":"C","text":"$21$"},{"key":"D","text":"$32$"}]$lyceon_json$::jsonb, 'A', NULL, E'Substituting $x = 3$ into $f(x) = 7x - 11$ gives $f(3) = 7(3) - 11 = 21 - 11 = 10$. The value $-32$ results from negating the product and subtracting: $-(21) - 11$. The value $21$ comes from computing $7(3)$ but neglecting to subtract $11$. The value $32$ comes from incorrectly adding $21 + 11$ instead of subtracting.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2J6IHZK', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 1, 'grid_in', E'What is the positive solution to $5x^2 - 320 = 0$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '8', ARRAY['8'], E'Adding 320 to both sides gives $5x^2 = 320$. Dividing by 5 yields $x^2 = 64$, so $x = \\pm 8$. The positive value is $8$.', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2JJT2S7', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 2, 'mcq', E'A factory produces 162 units of a product in 9 hours. Due to a machine upgrade, production speed increases by $\\frac{1}{3}$. At the new rate, how many units does the factory produce in 7 hours?', NULL, $lyceon_json$[{"key":"A","text":"126"},{"key":"B","text":"168"},{"key":"C","text":"189"},{"key":"D","text":"151"}]$lyceon_json$::jsonb, 'B', NULL, E'The original rate is $\\frac{162}{9} = 18$ units per hour. An increase of $\\frac{1}{3}$ gives a new rate of $18 + \\frac{18}{3} = 18 + 6 = 24$ units per hour. In 7 hours: $24 \\times 7 = 168$ units. The value 126 comes from using the original rate without the increase: $18 \\times 7 = 126$. The value 189 results from applying the $\\frac{1}{3}$ increase to the total production rather than the rate: $162 + \\frac{162}{3} \\times \\frac{7}{9}$, a misapplied calculation. The value 151 comes from adding a $\\frac{1}{3}$ increase to the 126 original-rate output incorrectly: $126 + \\frac{126}{3} \\approx 126 + 42 = 168$, but with an arithmetic slip yielding 151.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2JUPTFP', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 1, 'mcq', E'A rectangular garden has a length of $17$ meters and a width of $11$ meters. What is the area, in square meters, of the garden?', NULL, $lyceon_json$[{"key":"A","text":"56"},{"key":"B","text":"153"},{"key":"C","text":"170"},{"key":"D","text":"187"}]$lyceon_json$::jsonb, 'D', NULL, E'The area of a rectangle is length times width: $17 \\times 11 = 187$ square meters. The value $56$ results from computing the perimeter $2(17 + 11) = 56$ instead of the area. The value $153$ results from computing $17 \\times 9$ by mistake. The value $170$ results from computing $17 \\times 10$ instead of $17 \\times 11$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2JZAP98', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 2, 'mcq', E'Two parallel lines are cut by a transversal. One of the angles formed measures $131°$. A triangle is formed by the transversal, one of the parallel lines, and a line segment connecting them, where the angle at the second parallel line measures $38°$. What is the measure, in degrees, of the third angle of this triangle?', NULL, $lyceon_json$[{"key":"A","text":"11"},{"key":"B","text":"49"},{"key":"C","text":"93"},{"key":"D","text":"131"}]$lyceon_json$::jsonb, 'C', NULL, E'When two parallel lines are cut by a transversal, consecutive interior angles are supplementary. The angle inside the triangle at the first parallel line is $180° - 131° = 49°$. The angle at the second parallel line is $38°$. The third angle of the triangle is $180° - 49° - 38° = 93°$. The value $11°$ comes from computing $49° - 38°$ instead of using the triangle angle sum. The value $49°$ is the supplementary angle alone, ignoring the rest of the triangle. The value $131°$ mistakes the exterior angle for the interior angle.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2K2WUZZ', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 2, 'mcq', E'A line passes through the points $(2, -5)$ and $(-4, 7)$. What is the $y$-intercept of this line?', NULL, $lyceon_json$[{"key":"A","text":"$-9$"},{"key":"B","text":"$-2$"},{"key":"C","text":"$-1$"},{"key":"D","text":"$1$"}]$lyceon_json$::jsonb, 'C', NULL, E'The correct answer is $-1$. First find the slope: $m = \\frac{7 - (-5)}{-4 - 2} = \\frac{12}{-6} = -2$. Using point-slope form with $(2, -5)$: $y - (-5) = -2(x - 2)$, which simplifies to $y + 5 = -2x + 4$, so $y = -2x - 1$. The $y$-intercept is $-1$. The value $-9$ results from incorrectly using a positive slope of $2$, which gives $y = 2x - 9$. The value $-2$ is the slope of the line, not the $y$-intercept. The value $1$ results from a sign error when simplifying the constant term.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2KD2JU3', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 3, 'mcq', E'The system of equations $y = x^2 - 2x + 1$ and $y = 6x - 14$ has two solutions, $(x_1, y_1)$ and $(x_2, y_2)$. What is the value of $y_1 + y_2$?', NULL, $lyceon_json$[{"key":"A","text":"$8$"},{"key":"B","text":"$20$"},{"key":"C","text":"$12$"},{"key":"D","text":"$-20$"}]$lyceon_json$::jsonb, 'B', NULL, E'Setting the equations equal: $x^2 - 2x + 1 = 6x - 14$ gives $x^2 - 8x + 15 = 0$, which factors as $(x - 3)(x - 5) = 0$, so $x_1 = 3$ and $x_2 = 5$. Substituting into $y = 6x - 14$: $y_1 = 6(3) - 14 = 4$ and $y_2 = 6(5) - 14 = 16$, so $y_1 + y_2 = 20$. The value $8$ is $x_1 + x_2$, not $y_1 + y_2$. The value $12$ is $y_2 - y_1$, which is the difference rather than the sum. The value $-20$ applies an incorrect sign to the correct magnitude.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2MXCOI8', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 2, 'mcq', E'A theater sells adult tickets for $\\$14$ each and child tickets for $\\$9$ each. For a certain performance, $83$ tickets were sold for a total of $\\$942$. How many adult tickets were sold?', NULL, $lyceon_json$[{"key":"A","text":"$39$"},{"key":"B","text":"$44$"},{"key":"C","text":"$37$"},{"key":"D","text":"$46$"}]$lyceon_json$::jsonb, 'A', NULL, E'Let $a$ be the number of adult tickets and $c$ the number of child tickets. Then $a + c = 83$ and $14a + 9c = 942$. Substituting $c = 83 - a$ into the revenue equation: $14a + 9(83 - a) = 942$, so $14a + 747 - 9a = 942$, giving $5a = 195$ and $a = 39$. The value $44$ is the number of child tickets ($83 - 39 = 44$), not adult tickets. The value $37$ results from an error when setting up the substitution or combining like terms. The value $46$ comes from an arithmetic slip in the subtraction $942 - 747$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2NARIR3', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 2, 'mcq', E'A health researcher wants to determine whether a new vitamin supplement causes improved sleep quality. She recruits 120 volunteers and randomly assigns 60 to take the supplement daily and 60 to take a placebo daily for 8 weeks. At the end of the study, the supplement group reports significantly better sleep quality. Which of the following is the most appropriate conclusion?', NULL, $lyceon_json$[{"key":"A","text":"The supplement causes improved sleep quality in all adults."},{"key":"B","text":"The supplement causes improved sleep quality among the volunteers in the study."},{"key":"C","text":"There is an association between the supplement and improved sleep quality, but causation cannot be established."},{"key":"D","text":"The study's results are invalid because the sample is not large enough."}]$lyceon_json$::jsonb, 'B', NULL, E'Because the researcher used random assignment to treatment and control groups, a cause-and-effect conclusion is supported for the study participants. Random assignment allows causal inference within the experimental group. However, since the volunteers were not randomly selected from a broader population, the causal conclusion applies only to the volunteers, not to all adults. The claim that the supplement causes improvement in all adults overgeneralizes beyond the study population. The claim that causation cannot be established is incorrect because random assignment specifically enables causal inference, unlike an observational study. The claim that the sample is too small is unsupported; 120 participants with random assignment can yield valid experimental conclusions.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2NEQCTW', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 1, 'mcq', E'What is the value of $x$ in the solution to the system of equations $x + y = 17$ and $x - y = 3$?', NULL, $lyceon_json$[{"key":"A","text":"$7$"},{"key":"B","text":"$10$"},{"key":"C","text":"$14$"},{"key":"D","text":"$20$"}]$lyceon_json$::jsonb, 'B', NULL, E'Adding the two equations gives $(x + y) + (x - y) = 17 + 3$, which simplifies to $2x = 20$, so $x = 10$. The value $7$ is the $y$-value of the solution (since $10 + y = 17$ gives $y = 7$), not the requested $x$-value. The value $14$ results from subtracting $3$ from $17$ without accounting for the elimination step. The value $20$ comes from omitting the division by $2$ after finding $2x = 20$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2OCSGKH', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 1, 'mcq', E'Which value of $x$ satisfies the inequality $3x + 7 > 34$?', NULL, $lyceon_json$[{"key":"A","text":"$8$"},{"key":"B","text":"$9$"},{"key":"C","text":"$10$"},{"key":"D","text":"$7$"}]$lyceon_json$::jsonb, 'C', NULL, E'Solving $3x + 7 > 34$ gives $3x > 27$, so $x > 9$. Among the choices, only $10$ is strictly greater than $9$. The value $9$ fails because $3(9) + 7 = 34$, which equals but is not strictly greater than $34$. The value $8$ gives $3(8) + 7 = 31$, which is less than $34$. The value $7$ gives $3(7) + 7 = 28$, which is also less than $34$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2OWD6KJ', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 2, 'mcq', E'A data set consists of the values 13, 17, 19, 21, 21, 23, 29, 31, and 37. If the value 37 is removed from the data set, which of the following correctly describes the change in the mean and median?', NULL, $lyceon_json$[{"key":"A","text":"Both the mean and the median decrease."},{"key":"B","text":"The mean decreases, but the median stays the same."},{"key":"C","text":"The mean stays the same, but the median decreases."},{"key":"D","text":"Both the mean and the median stay the same."}]$lyceon_json$::jsonb, 'B', NULL, E'For the original 9 values, the sum is $13 + 17 + 19 + 21 + 21 + 23 + 29 + 31 + 37 = 211$, so the mean is $\\frac{211}{9} \\approx 23.44$. The median (the 5th value in sorted order) is 21. After removing 37, the 8 remaining values sum to $174$, giving a mean of $\\frac{174}{8} = 21.75$, which is lower than $23.44$. The median of 8 values is the average of the 4th and 5th values: the sorted set is $\\{13, 17, 19, 21, 21, 23, 29, 31\\}$, so the median is $\\frac{21 + 21}{2} = 21$, unchanged. Therefore the mean decreases but the median stays the same. The claim that both decrease is wrong because the median remains 21. The claim that the mean stays the same is wrong because removing a value above the mean lowers the mean. The claim that both stay the same ignores the effect on the mean.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2P3E4Z5', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 2, 'mcq', E'A circle in the $xy$-plane has center $(-3, 5)$ and passes through the point $(9, 0)$. What is the equation of this circle?', NULL, $lyceon_json$[{"key":"A","text":"$(x + 3)^2 + (y - 5)^2 = 169$"},{"key":"B","text":"$(x - 3)^2 + (y + 5)^2 = 169$"},{"key":"C","text":"$(x + 3)^2 + (y - 5)^2 = 13$"},{"key":"D","text":"$(x + 3)^2 + (y - 5)^2 = 119$"}]$lyceon_json$::jsonb, 'A', NULL, E'The radius is the distance from the center $(-3, 5)$ to the point $(9, 0)$: $r = \\sqrt{(9 - (-3))^2 + (0 - 5)^2} = \\sqrt{12^2 + (-5)^2} = \\sqrt{144 + 25} = \\sqrt{169} = 13$. The equation is $(x - (-3))^2 + (y - 5)^2 = 13^2$, which simplifies to $(x + 3)^2 + (y - 5)^2 = 169$. The equation $(x - 3)^2 + (y + 5)^2 = 169$ uses wrong signs for the center coordinates. The equation with $= 13$ uses $r$ instead of $r^2$. The equation with $= 119$ results from computing $12^2 - 5^2$ instead of $12^2 + 5^2$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2P62ZYH', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 3, 'mcq', E'The function $f$ is defined by $f(x) = a \\cdot b^x$, where $a$ and $b$ are positive constants. If $f(2) = 54$ and $f(5) = 1458$, what is the value of $a$?', NULL, $lyceon_json$[{"key":"A","text":"$6$"},{"key":"B","text":"$2$"},{"key":"C","text":"$3$"},{"key":"D","text":"$9$"}]$lyceon_json$::jsonb, 'A', NULL, E'From $f(2) = a \\cdot b^2 = 54$ and $f(5) = a \\cdot b^5 = 1458$, dividing the second equation by the first gives $b^3 = \\frac{1458}{54} = 27$, so $b = 3$. Substituting back: $a \\cdot 3^2 = 54$, which gives $a \\cdot 9 = 54$ and $a = 6$. The value $2$ comes from dividing $54$ by $27$ (the value of $b^3$) instead of by $b^2 = 9$. The value $3$ is the base $b$, not the coefficient $a$. The value $9$ is $b^2$, confusing the intermediate computation with the final answer.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2PY6V53', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 2, 'grid_in', E'The function $h$ is defined by $h(x) = x^3 - 6x^2 + 11x - 6$. Given that $h(1) = 0$, what is the sum of all values of $x$ for which $h(x) = 0$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '6', ARRAY['6'], E'Since $h(1) = 0$, the factor $(x - 1)$ divides $h(x)$. Performing polynomial long division: $x^3 - 6x^2 + 11x - 6 = (x - 1)(x^2 - 5x + 6) = (x - 1)(x - 2)(x - 3)$. The zeros are $x = 1$, $x = 2$, and $x = 3$, and their sum is $1 + 2 + 3 = 6$. Alternatively, by Vieta''s formulas the sum of the roots of $x^3 - 6x^2 + 11x - 6 = 0$ equals $\\frac{6}{1} = 6$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2QMK4UP', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 3, 'mcq', E'The solution set of the compound inequality $\\frac{2x - 5}{3} \\leq 7$ and $\\frac{4x + 1}{5} > 3$ can be written as $a < x \\leq b$ for constants $a$ and $b$. What is the value of $b - a$?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{19}{2}$"},{"key":"B","text":"$\\frac{33}{2}$"},{"key":"C","text":"$7$"},{"key":"D","text":"$9$"}]$lyceon_json$::jsonb, 'A', NULL, E'From $\\frac{2x - 5}{3} \\leq 7$: multiply both sides by $3$ to get $2x - 5 \\leq 21$, add $5$ to get $2x \\leq 26$, so $x \\leq 13$. Thus $b = 13$. From $\\frac{4x + 1}{5} > 3$: multiply both sides by $5$ to get $4x + 1 > 15$, subtract $1$ to get $4x > 14$, so $x > \\frac{7}{2}$. Thus $a = \\frac{7}{2}$. Therefore $b - a = 13 - \\frac{7}{2} = \\frac{26}{2} - \\frac{7}{2} = \\frac{19}{2}$. The value $\\frac{33}{2}$ results from adding $13 + \\frac{7}{2}$ instead of subtracting. The value $7$ results from omitting the step of adding $5$ in the first inequality, giving $b = \\frac{21}{2}$, then $\\frac{21}{2} - \\frac{7}{2} = 7$. The value $9$ results from rounding $\\frac{7}{2}$ up to $4$ and computing $13 - 4$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2RNYBOQ', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 3, 'grid_in', E'The function $y = 2x^2 - 13x + 21$ has two real zeros that lie on the $x$-axis at two points. What is the greater of the two $x$-intercepts?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '7/2', ARRAY['7/2', '3.5'], E'Setting $y = 0$: $2x^2 - 13x + 21 = 0$. The discriminant is $(-13)^2 - 4(2)(21) = 169 - 168 = 1$. Applying the quadratic formula: $x = \\frac{13 \\pm \\sqrt{1}}{4} = \\frac{13 \\pm 1}{4}$. This gives $x = \\frac{14}{4} = \\frac{7}{2}$ or $x = \\frac{12}{4} = 3$. Since $\\frac{7}{2} = 3.5 > 3$, the greater $x$-intercept is $\\frac{7}{2}$.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2RUYXSA', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 2, 'mcq', E'The population of a town was 12,500 at the start of 2021. The population increased by $8\\%$ from 2021 to 2022, then decreased by $5\\%$ from 2022 to 2023. What was the population at the start of 2023?', NULL, $lyceon_json$[{"key":"A","text":"12,875"},{"key":"B","text":"12,500"},{"key":"C","text":"12,825"},{"key":"D","text":"12,350"}]$lyceon_json$::jsonb, 'C', NULL, E'After the $8\\%$ increase: $12{,}500 \\times 1.08 = 13{,}500$. After the $5\\%$ decrease: $13{,}500 \\times 0.95 = 12{,}825$. The value $12{,}875$ results from applying both percentages to the original amount: $12{,}500 + 1{,}000 - 625 = 12{,}875$, which incorrectly computes the $5\\%$ decrease on $12{,}500$ instead of $13{,}500$. The value $12{,}500$ assumes the increase and decrease cancel out, ignoring that they apply to different base values. The value $12{,}350$ comes from subtracting $5\\%$ of $13{,}500$ twice or from an arithmetic slip in the multiplication.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2S0VRHW', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 2, 'mcq', E'Which expression is equivalent to $6x^2 + 17x - 14$?', NULL, $lyceon_json$[{"key":"A","text":"$(3x + 2)(2x - 7)$"},{"key":"B","text":"$(6x - 2)(x + 7)$"},{"key":"C","text":"$(3x - 2)(2x + 7)$"},{"key":"D","text":"$(3x - 7)(2x + 2)$"}]$lyceon_json$::jsonb, 'C', NULL, E'To factor $6x^2 + 17x - 14$, find two numbers that multiply to $6 \\times (-14) = -84$ and add to $17$: those are $21$ and $-4$. Rewrite: $6x^2 + 21x - 4x - 14 = 3x(2x + 7) - 2(2x + 7) = (3x - 2)(2x + 7)$. Expanding $(3x + 2)(2x - 7)$ gives $6x^2 - 17x - 14$, which has the wrong sign on the middle term. Expanding $(6x - 2)(x + 7)$ gives $6x^2 + 40x - 14$, which has the wrong middle coefficient. Expanding $(3x - 7)(2x + 2)$ gives $6x^2 - 8x - 14$, which also has the wrong middle term.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2T2N29D', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 2, 'mcq', E'A random sample of 250 registered voters in a city found that $58\\%$ support a proposed park renovation, with a margin of error of $4\\%$. Which of the following is the best interpretation of this result?', NULL, $lyceon_json$[{"key":"A","text":"Exactly $58\\%$ of all registered voters in the city support the renovation."},{"key":"B","text":"Between $54\\%$ and $62\\%$ of the sampled voters support the renovation."},{"key":"C","text":"It is plausible that between $54\\%$ and $62\\%$ of all registered voters in the city support the renovation."},{"key":"D","text":"If another sample is taken, exactly $58\\%$ of that sample will support the renovation."}]$lyceon_json$::jsonb, 'C', NULL, E'A margin of error of $4\\%$ around a sample proportion of $58\\%$ produces a confidence interval of $54\\%$ to $62\\%$. This interval estimates the true population proportion, meaning it is plausible that between $54\\%$ and $62\\%$ of all registered voters in the city support the renovation. The statement that exactly $58\\%$ of all voters support the renovation ignores sampling uncertainty. The statement about the sampled voters is incorrect because the $58\\%$ is already known exactly for the sample; the margin of error applies to the population inference. The claim that another sample would yield exactly $58\\%$ misunderstands sampling variability.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2T6OT8Z', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 2, 'mcq', E'An exponential function is defined by $p(t) = 250 \\cdot (1.06)^t$, where $t$ is the number of years after 2020. Which of the following is the best interpretation of $1.06$ in this context?', NULL, $lyceon_json$[{"key":"A","text":"The quantity increases by $6\\%$ each year"},{"key":"B","text":"The quantity increases by $106$ units each year"},{"key":"C","text":"The quantity decreases by $6\\%$ each year"},{"key":"D","text":"The initial quantity in 2020 is $1.06$ times the quantity at time $t$"}]$lyceon_json$::jsonb, 'A', NULL, E'In the exponential model $p(t) = 250 \\cdot (1.06)^t$, the base $1.06 = 1 + 0.06$ represents a $6\\%$ increase each year. The claim of a $106$-unit yearly increase confuses exponential growth with linear growth and misreads the growth factor as an additive constant. The claim of a $6\\%$ decrease is wrong because a base greater than $1$ indicates growth, not decay. The claim that the initial quantity is $1.06$ times the quantity at time $t$ reverses the relationship: $p(t)$ grows over time, so later values exceed the initial value, not the other way around.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2TGQB63', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 2, 'mcq', E'For what value of $c$ does $x^2 + 14x + c = 0$ have exactly one real solution?', NULL, $lyceon_json$[{"key":"A","text":"$7$"},{"key":"B","text":"$14$"},{"key":"C","text":"$49$"},{"key":"D","text":"$196$"}]$lyceon_json$::jsonb, 'C', NULL, E'A quadratic $x^2 + 14x + c = 0$ has exactly one real solution when the discriminant equals zero: $14^2 - 4(1)(c) = 0$, so $196 - 4c = 0$, giving $c = 49$. The value $7$ comes from halving $14$ rather than computing $\\frac{14^2}{4}$. The value $14$ confuses the coefficient $b$ with the required value of $c$. The value $196$ results from setting $c = b^2$ instead of $c = \\frac{b^2}{4}$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2U2I49E', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 1, 'mcq', E'Which of the following is equivalent to $3x^2 - 7x + 11 + 5x^2 + 4x - 9$?', NULL, $lyceon_json$[{"key":"A","text":"$8x^2 - 3x + 2$"},{"key":"B","text":"$8x^2 - 11x + 2$"},{"key":"C","text":"$2x^2 - 3x + 2$"},{"key":"D","text":"$8x^2 - 3x + 20$"}]$lyceon_json$::jsonb, 'A', NULL, E'Combining like terms: the $x^2$ terms give $3x^2 + 5x^2 = 8x^2$, the $x$ terms give $-7x + 4x = -3x$, and the constants give $11 + (-9) = 2$. The result is $8x^2 - 3x + 2$. The expression $8x^2 - 11x + 2$ incorrectly subtracts the $x$ terms ($-7x - 4x$) instead of adding. The expression $2x^2 - 3x + 2$ incorrectly subtracts the $x^2$ terms ($5x^2 - 3x^2$). The expression $8x^2 - 3x + 20$ incorrectly adds the constants as $11 + 9$ instead of $11 + (-9)$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2U502R4', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 1, 'mcq', E'The function $f$ is defined by $f(x) = 3x^2 - 7$. What is the value of $f(4)$?', NULL, $lyceon_json$[{"key":"A","text":"$41$"},{"key":"B","text":"$5$"},{"key":"C","text":"$48$"},{"key":"D","text":"$55$"}]$lyceon_json$::jsonb, 'A', NULL, E'Substituting $x = 4$: $f(4) = 3(4)^2 - 7 = 3(16) - 7 = 48 - 7 = 41$. The value $5$ results from computing $3(4) - 7 = 5$, forgetting to square before multiplying. The value $48$ comes from calculating $3(16) = 48$ but omitting the subtraction of $7$. The value $55$ results from adding $7$ instead of subtracting it: $48 + 7 = 55$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2VZCT7R', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 3, 'grid_in', E'The expression $\\frac{3x^3 + 11x^2 - 4x}{x^2 + 5x}$ can be rewritten in the form $ax + b + \\frac{c}{x + 5}$, where $a$, $b$, and $c$ are constants. What is the value of $a + b + c$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '15', ARRAY['15'], E'First simplify by factoring $x$ from both numerator and denominator: $\\frac{x(3x^2 + 11x - 4)}{x(x + 5)} = \\frac{3x^2 + 11x - 4}{x + 5}$. Perform polynomial long division. Divide $3x^2$ by $x$ to get $3x$. Multiply: $3x(x + 5) = 3x^2 + 15x$. Subtract: $(3x^2 + 11x - 4) - (3x^2 + 15x) = -4x - 4$. Divide $-4x$ by $x$ to get $-4$. Multiply: $-4(x + 5) = -4x - 20$. Subtract: $(-4x - 4) - (-4x - 20) = 16$. So the expression equals $3x - 4 + \\frac{16}{x + 5}$, meaning $a = 3$, $b = -4$, and $c = 16$. Therefore $a + b + c = 3 + (-4) + 16 = 15$.', NULL, NULL, 'draft', 1, 110, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2WQSNVA', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 1, 'mcq', E'In a right triangle, one leg has length $16$ and the hypotenuse has length $34$. What is the length of the other leg?', NULL, $lyceon_json$[{"key":"A","text":"$30$"},{"key":"B","text":"$18$"},{"key":"C","text":"$\\sqrt{1412}$"},{"key":"D","text":"$50$"}]$lyceon_json$::jsonb, 'A', NULL, E'Using the Pythagorean theorem, $a^2 + 16^2 = 34^2$, so $a^2 = 1156 - 256 = 900$ and $a = 30$. The value $18$ results from computing $34 - 16$ instead of using the theorem. The value $\\sqrt{1412}$ comes from adding $16^2 + 34^2$ instead of subtracting. The value $50$ results from adding $16 + 34$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2WWUVIX', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 2, 'mcq', E'In right triangle $DEF$, angle $F = 90°$, $DE = 29$, and $\\sin(D) = \\frac{20}{29}$. What is the length of side $DF$?', NULL, $lyceon_json$[{"key":"A","text":"9"},{"key":"B","text":"20"},{"key":"C","text":"21"},{"key":"D","text":"$29$"}]$lyceon_json$::jsonb, 'C', NULL, E'In right triangle $DEF$ with the right angle at $F$, side $DE$ is the hypotenuse. Since $\\sin(D) = \\frac{\\text{opposite}}{\\text{hypotenuse}} = \\frac{EF}{DE}$, we get $EF = 20$. The side $DF$ is adjacent to angle $D$, so $DF = \\sqrt{DE^2 - EF^2} = \\sqrt{29^2 - 20^2} = \\sqrt{841 - 400} = \\sqrt{441} = 21$. The value $9$ comes from computing $29 - 20$ instead of using the Pythagorean theorem. The value $20$ confuses the opposite side with the adjacent side. The unsimplified form $\\sqrt{441}$ is numerically equal to $21$ but reflects failing to evaluate the square root.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2WYDEIF', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 1, 'mcq', E'If $5x + 17 = 52$, what is the value of $x$?', NULL, $lyceon_json$[{"key":"A","text":"$-7$"},{"key":"B","text":"$7$"},{"key":"C","text":"$\\frac{52}{5}$"},{"key":"D","text":"$35$"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct answer is $7$. Subtract $17$ from both sides of $5x + 17 = 52$ to get $5x = 35$, then divide both sides by $5$ to get $x = 7$. The value $-7$ results from a sign error when dividing. The value $\\frac{52}{5}$ comes from dividing $52$ by $5$ without first subtracting $17$. The value $35$ is the intermediate result $5x = 35$ before dividing by $5$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2X0CAQ4', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 1, 'grid_in', E'What is the value of $x$ if $3x - 11 = 46$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '19', ARRAY['19'], E'Add $11$ to both sides of $3x - 11 = 46$ to get $3x = 57$. Divide both sides by $3$ to get $x = 19$.', NULL, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2XBW3EA', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 1, 'mcq', E'What is the positive solution to the equation $x^2 - 49 = 0$?', NULL, $lyceon_json$[{"key":"A","text":"$7$"},{"key":"B","text":"$-7$"},{"key":"C","text":"$49$"},{"key":"D","text":"$\\sqrt{7}$"}]$lyceon_json$::jsonb, 'A', NULL, E'The equation $x^2 - 49 = 0$ can be rewritten as $x^2 = 49$, so $x = \\pm 7$. The positive solution is $7$. The value $-7$ is the negative solution, not the positive one the question asks for. The value $49$ results from confusing $x^2 = 49$ with $x = 49$, failing to take the square root. The value $\\sqrt{7}$ comes from incorrectly applying the square root to the coefficient $7$ rather than to $49$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Z4J28F', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 2, 'mcq', E'The function $g$ is defined by $g(x) = -2(x + 4)^2 + 18$. What is the maximum value of $g(x)$?', NULL, $lyceon_json$[{"key":"A","text":"$-4$"},{"key":"B","text":"$18$"},{"key":"C","text":"$-2$"},{"key":"D","text":"$50$"}]$lyceon_json$::jsonb, 'B', NULL, E'The function is in vertex form $g(x) = a(x - h)^2 + k$ with $a = -2$, $h = -4$, and $k = 18$. Since $a < 0$, the parabola opens downward and the vertex is the highest point, giving a maximum value of $18$. The value $-4$ is the $x$-coordinate of the vertex, not the maximum output of the function. The value $-2$ is the leading coefficient and does not represent any output value. The value $50$ comes from incorrectly computing $|-2|(16) + 18 = 50$, treating the squared term as adding rather than subtracting.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Z8HC3N', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 3, 'mcq', E'A linear function $h$ satisfies $h(4) = 23$ and $h(11) = -12$. For what value of $x$ does $h(x) = 0$?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{43}{5}$"},{"key":"B","text":"$-\\frac{3}{5}$"},{"key":"C","text":"$\\frac{23}{5}$"},{"key":"D","text":"$\\frac{12}{5}$"}]$lyceon_json$::jsonb, 'A', NULL, E'The slope is $\\frac{-12 - 23}{11 - 4} = \\frac{-35}{7} = -5$. Using point-slope form with the point $(4, 23)$: $h(x) = -5(x - 4) + 23 = -5x + 20 + 23 = -5x + 43$. Setting $h(x) = 0$ gives $-5x + 43 = 0$, so $x = \\frac{43}{5}$. The value $-\\frac{3}{5}$ results from using a slope of $+5$ (sign error), yielding $h(x) = 5x + 3$ and $x = -\\frac{3}{5}$. The value $\\frac{23}{5}$ comes from dividing $h(4) = 23$ by the slope magnitude without constructing the full equation. The value $\\frac{12}{5}$ comes from dividing $|h(11)| = 12$ by the slope magnitude.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ZGDB5P', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 2, 'mcq', E'What is the value of $x$ in the equation $\\frac{2x - 9}{7} = 5$?', NULL, $lyceon_json$[{"key":"A","text":"$-22$"},{"key":"B","text":"$13$"},{"key":"C","text":"$22$"},{"key":"D","text":"$44$"}]$lyceon_json$::jsonb, 'C', NULL, E'The correct answer is $22$. Multiply both sides of $\\frac{2x - 9}{7} = 5$ by $7$ to get $2x - 9 = 35$. Add $9$ to both sides to get $2x = 44$, then divide by $2$ to get $x = 22$. The value $-22$ results from a sign error. The value $13$ comes from subtracting $9$ from $35$ instead of adding it, yielding $2x = 26$ and $x = 13$. The value $44$ is the result of stopping at $2x = 44$ without dividing by $2$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ZIPP5W', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 2, 'grid_in', E'Line $\\ell$ has the equation $4x + 9y = 36$. What is the $x$-intercept of line $\\ell$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '9', ARRAY['9'], E'To find the $x$-intercept, set $y = 0$ in the equation $4x + 9y = 36$. This gives $4x + 0 = 36$, so $4x = 36$ and $x = 9$. The $x$-intercept is $9$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ZQ9YA6', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 3, 'mcq', E'The line $3x - 2y = 19$ passes through the point $(a + 4, a - 1)$. What is the value of $a$?', NULL, $lyceon_json$[{"key":"A","text":"$-5$"},{"key":"B","text":"$5$"},{"key":"C","text":"$9$"},{"key":"D","text":"$30$"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct answer is $5$. Substitute $x = a + 4$ and $y = a - 1$ into $3x - 2y = 19$: $3(a + 4) - 2(a - 1) = 19$. Distribute to get $3a + 12 - 2a + 2 = 19$. Combine like terms: $a + 14 = 19$, so $a = 5$. The value $-5$ results from a sign error when solving the final step. The value $9$ comes from incorrectly distributing $-2(a - 1)$ as $-2a - 2$ instead of $-2a + 2$, which gives $a + 10 = 19$ and $a = 9$. The value $30$ comes from swapping the coordinates, substituting $(a - 1, a + 4)$ instead of $(a + 4, a - 1)$, which gives $3(a - 1) - 2(a + 4) = 19$, leading to $a - 11 = 19$ and $a = 30$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
