INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2093L81', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice most logically completes the text?', E'Psychologist Mariana Voss conducted a series of experiments in which participants solved anagram puzzles while ambient noise levels varied. Participants exposed to moderate background noise of roughly 70 decibels solved puzzles more quickly than those working in near-silence. Voss attributed this to a phenomenon she termed "constructive distraction," in which mild sensory input prevents the mind from overthinking simple tasks. ______, when noise levels exceeded 85 decibels, puzzle-solving speed declined sharply, suggesting that the benefit is confined to a narrow acoustic range.', $lyceon_json$[{"key":"A","text":"In other words,"},{"key":"B","text":"Crucially, however,"},{"key":"C","text":"By the same token,"},{"key":"D","text":"To illustrate this point further,"}]$lyceon_json$::jsonb, 'B', NULL, E'The final sentence introduces a critical qualification to Voss''s finding: the benefit of noise exists only within a limited range, and higher levels actually impair performance. "Crucially, however" correctly signals both the importance and the contrasting nature of this limitation. "In other words" would indicate a restatement of the previous idea, but the final sentence introduces new, contrasting information rather than rephrasing the constructive distraction concept. "By the same token" implies that the final sentence extends the same logic, when it actually restricts it by showing where the pattern breaks down. "To illustrate this point further" suggests the final sentence provides another example supporting the same claim, but the sentence instead undercuts the claim by showing its boundary.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
