INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2401MNV', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 1, 'mcq', E'Which choice is most logically supported by the information in the passage?', E'When textile manufacturer Luís Ferreira introduced automated looms to his factory in Porto in 1987, he expected productivity to double within a year. Instead, output rose only 14 percent in the first twelve months. An internal review revealed that the automated looms, while faster, required a different type of thread preparation that the existing workforce had not been trained to perform. Workers spent an average of 23 minutes per shift correcting thread jams that would not have occurred with manually operated looms.', $lyceon_json$[{"key":"A","text":"The automated looms were mechanically defective and needed to be replaced with a different model to achieve the expected productivity gains."},{"key":"B","text":"If the workforce had received appropriate training in the thread preparation required by the automated looms, productivity gains would likely have been closer to Ferreira's expectations."},{"key":"C","text":"Manual looms are generally more reliable than automated looms across all textile manufacturing contexts and should be preferred by factory managers."},{"key":"D","text":"Ferreira's factory ultimately abandoned the automated looms and reverted to manual production within two years of the initial installation."}]$lyceon_json$::jsonb, 'B', NULL, E'The passage identifies the gap between expected and actual productivity as resulting from workers lacking training for the new thread preparation, causing time-consuming jams. It follows logically that proper training would have reduced or eliminated those jams, bringing output closer to the projected doubling. The claim that the looms were defective contradicts the passage, which attributes the shortfall to workforce preparation, not to mechanical problems. The claim that manual looms are generally more reliable makes a sweeping generalization unsupported by this single case. The claim about abandoning the automated looms introduces an outcome the passage never mentions or implies.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"detail_misread"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW26ZG9BT', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 3, 'mcq', E'Which choice most logically completes an inference supported by the passage?', E'Neuroscientist Yael Brenner has studied how experienced chess players evaluate board positions differently from novices. Using eye-tracking technology, Brenner found that expert players spend 60 percent of their analysis time examining pieces that are not currently under threat—pieces whose positional value may shift several moves into the future. Novices, by contrast, allocate roughly 80 percent of their time to pieces that are immediately threatened or threatening. Brenner also observed that when experts were shown board positions from games in an unfamiliar variant of chess with altered movement rules, their eye-tracking patterns shifted to resemble those of novices: they focused predominantly on immediately threatened pieces rather than on pieces with latent strategic value.', $lyceon_json$[{"key":"A","text":"Expert chess players' ability to evaluate long-term positional value depends heavily on their familiarity with the specific movement rules governing the game, rather than being a general perceptual skill transferable to any strategic context."},{"key":"B","text":"Novice chess players are inherently less capable of learning the movement rules of unfamiliar chess variants than expert players are, owing to fundamental differences in cognitive capacity."},{"key":"C","text":"Eye-tracking technology is unreliable as a measure of strategic thinking because it cannot distinguish between players who are planning ahead and those who are reacting to immediate threats."},{"key":"D","text":"Expert players deliberately adopt novice-like eye-tracking patterns when encountering unfamiliar game variants as a conscious strategy to recalibrate their analytical approach before shifting to more advanced techniques."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage shows that experts'' distinctive pattern of focusing on non-threatened pieces vanished when movement rules changed, reverting to the novice pattern. This implies their long-term positional evaluation depends on knowing the specific rules, not on a transferable general skill. The claim about novices being inherently less capable of learning new rules is unsupported; the passage discusses eye-tracking patterns, not learning capacity. The claim that eye-tracking is unreliable contradicts the passage''s use of it as a productive research tool that yielded meaningful distinctions. The claim about experts deliberately adopting novice patterns as a conscious recalibration strategy is unsupported; the passage describes an involuntary shift, not a deliberate tactic.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW27BGN1S', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 1, 'mcq', E'Which finding from Murakami''s survey, if accurate, most directly supports his hypothesis?', E'Ornithologist Kenji Murakami hypothesized that the sharp decline in barn owl populations along the Aomori coast of Japan was driven primarily by the conversion of traditional hay barns—the owls'' preferred nesting sites—into steel-frame storage buildings. To test this, Murakami surveyed 83 coastal properties in 2019, recording building type and evidence of barn owl nesting. He found that 31 of 39 remaining wooden barns showed signs of active or recent nesting, while only 2 of 44 steel-frame buildings did.', $lyceon_json$[{"key":"A","text":"Barn owls in the region had shifted their diet from rodents to marine invertebrates over the previous decade."},{"key":"B","text":"Wooden barns with active nesting were significantly more common than steel-frame buildings with active nesting."},{"key":"C","text":"The total number of coastal properties in Aomori had decreased substantially between 2010 and 2019."},{"key":"D","text":"Barn owl populations in inland areas of Aomori, where wooden barns remain prevalent, have stayed comparatively stable during the same period."}]$lyceon_json$::jsonb, 'B', NULL, E'Murakami''s hypothesis is that converting wooden barns to steel-frame buildings drove the owl population decline. The finding that wooden barns had far more nesting activity than steel-frame buildings directly supports the link between building type and nesting. The claim about a dietary shift is irrelevant to nesting site preference. The decrease in total coastal properties addresses a different variable entirely. The finding about stable inland populations where wooden barns remain is supportive but indirect—it does not come from the survey itself and addresses a different geographic area rather than directly connecting building type to nesting in the study area.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW281SDPB', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 2, 'mcq', E'As used in the passage,"compromise" most nearly means', E'The following passage is from a 2021 essay on ceramic restoration techniques.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW284W7OH', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Economist Priya Ranganathan has argued that micro-lending programs in rural Tamil Nadu often fail not because borrowers lack business acumen but because repayment schedules ignore seasonal income _______ harvests generate most of a household''s annual revenue within a narrow six-week window, yet loan installments remain fixed across all twelve months.', $lyceon_json$[{"key":"A","text":"fluctuations, for example,"},{"key":"B","text":"fluctuations:"},{"key":"C","text":"fluctuations, which"},{"key":"D","text":"fluctuations; which,"}]$lyceon_json$::jsonb, 'B', NULL, E'The blank falls after ''fluctuations,'' which ends the main claim, and before an independent clause that elaborates on that claim by specifying how seasonal income fluctuations operate. A colon is the correct punctuation because it introduces an explanation or elaboration of the preceding independent clause. Using ''for example,'' with commas creates a comma splice joining two independent clauses. Using ''which'' after a comma introduces a relative clause, but what follows is an independent clause with its own subject (''harvests'') and a coordinating conjunction (''yet'') joining a second independent clause, making the relative pronoun grammatically incorrect. Using a semicolon followed by ''which,'' is wrong because a semicolon should join independent clauses, and ''which'' would introduce a dependent fragment after the semicolon.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW28B4HUM', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The committee reviewing applications for the Ellsworth Grant, a fund established in 1953 to support independent documentary filmmakers, announced that each of the seventy-one proposals submitted this year _______ a detailed budget projection, though many applicants had neglected to include one in previous cycles.', $lyceon_json$[{"key":"A","text":"are requiring"},{"key":"B","text":"require"},{"key":"C","text":"have required"},{"key":"D","text":"requires"}]$lyceon_json$::jsonb, 'D', NULL, E'The subject of the verb in the blank is ''each,'' which is a singular indefinite pronoun regardless of the prepositional phrase ''of the seventy-one proposals'' that follows it. The verb must therefore be singular. Additionally, the clause is introduced by ''that'' after ''announced,'' placing the action in a reported-speech context where the present tense conveys an ongoing requirement. ''Requires'' is the correct singular present-tense form. ''Are requiring'' is plural and therefore disagrees with the singular subject ''each.'' ''Require'' is also a plural form that fails to agree with ''each.'' ''Have required'' is plural present perfect, which disagrees in number with the singular subject.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW29LN555', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The Galveston Hurricane of 1900, one of the deadliest natural disasters in United States history, _______ an estimated eight thousand lives and leveled much of the city''s infrastructure within a single night.', $lyceon_json$[{"key":"A","text":"claiming"},{"key":"B","text":"having claimed"},{"key":"C","text":"claimed"},{"key":"D","text":"to claim"}]$lyceon_json$::jsonb, 'C', NULL, E'The sentence requires a past-tense finite verb to serve as the main predicate of the subject ''The Galveston Hurricane of 1900.'' The appositive phrase ''one of the deadliest natural disasters in United States history'' is set off by commas and does not change the need for a main verb. ''Claimed'' is the simple past tense that correctly completes the sentence and pairs with the coordinating verb ''leveled.'' The present participle ''claiming'' cannot function as a finite verb without an auxiliary. The perfect participle ''having claimed'' is also a non-finite form that leaves the sentence without a main verb. The infinitive ''to claim'' cannot serve as the main predicate of the sentence.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
