INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2CANZUP', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 1, 'mcq', E'According to the passage, what is the main finding of Ševčíková''s study?', E'A 2021 study by marine ecologist Hana Ševčíková examined the distribution of bioluminescent organisms in the Adriatic Sea. Using trawl data collected over fourteen months, Ševčíková found that bioluminescent species were present at every depth sampled, from surface waters to the seafloor at 1,200 meters. However, the highest concentrations consistently appeared between 200 and 400 meters, a zone where light from the surface has nearly disappeared. Ševčíková concluded that the absence of sunlight at these depths likely intensifies the selective advantage of producing one''s own light, whether for attracting prey, deterring predators, or communicating with potential mates.', $lyceon_json$[{"key":"A","text":"Bioluminescent organisms in the Adriatic Sea are most concentrated at depths where sunlight is nearly absent."},{"key":"B","text":"The Adriatic Sea contains a wider diversity of bioluminescent species than other Mediterranean basins do."},{"key":"C","text":"Bioluminescent organisms cannot survive in surface waters because of interference from sunlight."},{"key":"D","text":"Bioluminescent organisms are most densely concentrated at depths between 200 and 400 meters, a finding that suggests the near-total absence of sunlight at those depths amplifies the evolutionary benefits of self-generated light."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage states that the highest concentrations of bioluminescent organisms appeared between 200 and 400 meters, where sunlight has nearly disappeared, and that this absence of light likely intensifies the advantage of producing one''s own light. The claim that bioluminescent organisms are most concentrated where sunlight is nearly absent directly captures this finding. The claim about wider diversity than other Mediterranean basins introduces a comparison the passage never makes. The claim that bioluminescent organisms cannot survive in surface waters contradicts the passage, which states they were found at every depth including the surface. The longest option restates the correct idea but adds unnecessary elaboration not required by the question.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2D12FRD', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'In 1987, archaeologist Dmitri Volshen uncovered a collection of obsidian tools at a site near Lake Borsuk in central Siberia. The tools, which predated earlier finds in the region by roughly three thousand _______ they were fashioned using a technique previously associated only with settlements much farther south.', $lyceon_json$[{"key":"A","text":"years; moreover,"},{"key":"B","text":"years, moreover,"},{"key":"C","text":"years, moreover"},{"key":"D","text":"years moreover,"}]$lyceon_json$::jsonb, 'A', NULL, E'The blank falls between two independent clauses. The first clause ends with ''years,'' and the second begins with the conjunctive adverb ''moreover.'' A semicolon before ''moreover'' correctly joins the two independent clauses, and a comma after the conjunctive adverb is standard usage. Using a comma before ''moreover'' with a comma after it produces a comma splice, since a comma alone cannot join two independent clauses with a conjunctive adverb. Using a comma before ''moreover'' without a following comma is also a comma splice and drops the required post-adverb comma. Omitting punctuation before ''moreover'' creates a run-on sentence.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2EVXMOI', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Marine biologist Tanya Orevillo has spent fourteen years studying the migratory patterns of leatherback sea turtles in the southeastern Pacific. Her research has demonstrated that water temperature shifts of even two degrees Celsius can alter nesting _______ Orevillo now advocates for expanded thermal monitoring along key coastal corridors.', $lyceon_json$[{"key":"A","text":"timelines, consequently,"},{"key":"B","text":"timelines, consequently"},{"key":"C","text":"timelines. Consequently,"},{"key":"D","text":"timelines consequently,"}]$lyceon_json$::jsonb, 'C', NULL, E'The blank sits between two independent clauses: one ending with the noun ''timelines'' and one beginning with the conjunctive adverb ''Consequently.'' Two independent clauses cannot be joined by a comma alone (that produces a comma splice) or by a conjunctive adverb without proper punctuation. A period after ''timelines'' followed by ''Consequently,'' (with a comma after the conjunctive adverb) correctly separates the two sentences. The choice using a comma before ''consequently'' with another comma after it creates a comma splice. The choice using a comma before ''consequently'' without a following comma also creates a comma splice and omits the required comma after the conjunctive adverb. The choice omitting all punctuation before ''consequently'' creates a run-on sentence.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2FJLJTK', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 2, 'mcq', E'Which choice best describes the main idea of the passage?', E'In the early twentieth century, Brazilian composer Heitor Villa-Lobos traveled extensively through rural Brazil, collecting folk melodies and rhythmic patterns from indigenous and Afro-Brazilian communities. Rather than simply transcribing these melodies, Villa-Lobos wove them into complex orchestral works that also drew on European classical forms such as the fugue and the string quartet. Some critics accused him of diluting authentic folk music by placing it within Western frameworks, while others praised him for creating a distinctly national art music that neither fully replicated folk traditions nor abandoned them. Villa-Lobos himself insisted that his goal was not preservation but transformation: giving local musical ideas a structural ambition they had never been asked to carry.', $lyceon_json$[{"key":"A","text":"Villa-Lobos sought to replace European classical forms with indigenous Brazilian musical traditions in his orchestral compositions."},{"key":"B","text":"Critics universally condemned Villa-Lobos for distorting Brazilian folk music by embedding it in European compositional structures."},{"key":"C","text":"Villa-Lobos combined Brazilian folk elements with European classical forms to create a national art music that transformed rather than preserved local traditions."},{"key":"D","text":"Villa-Lobos combined Brazilian folk melodies with European classical structures, an approach that sparked debate among critics but that the composer defended as a deliberate transformation of local musical ideas into works of greater structural ambition."}]$lyceon_json$::jsonb, 'C', NULL, E'The passage describes how Villa-Lobos merged folk melodies with European forms, generating both criticism and praise, and quotes the composer''s own goal of transformation rather than preservation. The choice stating he combined folk elements with European forms to create a transformative national art music captures this central idea. The claim that he sought to replace European forms with indigenous traditions reverses the relationship described in the passage; he merged the two rather than discarding one. The claim that critics universally condemned him contradicts the passage, which notes that some praised him. The longest option largely restates the correct idea with extra detail about the debate, but is not more accurate.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"detail_misread"},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2G88MMR', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 1, 'mcq', E'As used in the passage,"apparent" most nearly means', E'The following passage is from a 2019 article about municipal composting programs.
