INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2J0QP9B', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 3, 'mcq', E'Which choice best describes the author''s rhetorical strategy in this passage?', E'The following passage is from a 2023 essay by historian Mariana Solberg on the decline of handwritten correspondence.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2J13KRO', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 2, 'mcq', E'Which choice best describes the role of the isotope data in the passage?', E'Geochemist Élise Thibault has proposed that the high selenium content found in shale deposits of the Montérégie region in Québec originated not from local volcanic activity, as previously assumed, but from wind-transported ash released by eruptions along the proto-Atlantic rift more than 440 million years ago. Thibault notes that the selenium isotope ratios in Montérégie shale closely match those found in rift-associated basalts in present-day Morocco and Scotland, rather than those typical of the Canadian Shield''s own igneous formations. She also points out that prevailing wind models for the Late Ordovician place Montérégie directly downwind of the rift zone.', $lyceon_json$[{"key":"A","text":"It introduces a new hypothesis that competes with Thibault's wind-transport proposal and suggests the selenium could have a biological rather than geological origin."},{"key":"B","text":"It serves as evidence supporting Thibault's claim by showing the selenium matches distant rift sources rather than local igneous formations."},{"key":"C","text":"It establishes that volcanic eruptions along the proto-Atlantic rift were more frequent during the Late Ordovician than in any other geological period."},{"key":"D","text":"It demonstrates that selenium concentrations in Montérégie shale are unusually high compared with global averages for shale deposits of similar age."}]$lyceon_json$::jsonb, 'B', NULL, E'The passage presents the isotope data to support Thibault''s claim that the selenium was wind-transported from the rift zone: the ratios match rift-associated basalts in Morocco and Scotland, not local Canadian Shield formations. The choice stating the data serves as evidence for the wind-transport claim by matching distant sources captures this role. The claim about a competing biological hypothesis is fabricated; no such hypothesis appears in the passage. The claim about eruption frequency introduces information the passage never provides. The claim about unusually high concentrations compared with global averages addresses a different question—the quantity rather than the origin of the selenium.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"inference_overreach"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2J2TC1Z', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 2, 'mcq', E'Based on the texts, how does Park''s position relate to Fuentes''s claim about the cause of English loanword adoption in Korean?', E'Text 1
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2OF4BEG', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 3, 'mcq', E'Which choice best states the primary purpose of the passage?', E'Economist Priya Nandakumar has argued that microfinance programs in rural South Asia often fail not because borrowers lack business acumen but because the programs impose repayment schedules designed for urban wage-earners. Agricultural income is seasonal: farmers may earn most of their revenue during a narrow harvest window and face months of near-zero cash flow between plantings. When weekly repayments begin immediately after a loan is disbursed, borrowers with seasonal income must divert funds from productive investments—seeds, fertilizer, equipment repairs—to service debt before those investments can generate returns. Nandakumar''s proposal is not to eliminate repayment schedules but to restructure them around crop calendars, deferring the first payment until after the harvest and then concentrating repayments in the months when income actually arrives.', $lyceon_json$[{"key":"A","text":"To argue that microfinance programs should be abolished in favor of government agricultural subsidies across rural South Asia."},{"key":"B","text":"To explain how the mismatch between standard microfinance repayment schedules and seasonal agricultural income undermines borrower success, and to present a proposed remedy."},{"key":"C","text":"To demonstrate that farmers in rural South Asia are unable to manage complex financial products without external institutional support and oversight."},{"key":"D","text":"To contrast the financial behaviors of urban wage-earners with those of rural agricultural workers across multiple economic dimensions, including savings rates, credit utilization, and investment patterns."}]$lyceon_json$::jsonb, 'B', NULL, E'The passage identifies a specific problem—repayment schedules designed for urban wage-earners do not align with seasonal agricultural income—and then presents Nandakumar''s proposed fix of restructuring payments around crop calendars. The choice describing the mismatch and the proposed remedy captures this dual purpose. The claim about abolishing microfinance misrepresents the argument; Nandakumar proposes restructuring, not elimination. The claim that farmers cannot manage complex products contradicts the passage, which explicitly states borrowers do not lack business acumen. The choice about contrasting urban and rural financial behaviors across multiple dimensions overstates the scope of the passage, which addresses only repayment schedule timing.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"inference_overreach"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2ORN1L3', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 1, 'mcq', E'Which choice best describes the function of the third sentence in the overall structure of the passage?', E'The following passage is from a 2022 encyclopedia entry on bioluminescence.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2U8RS15', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Neither the lead vocalist nor the three backup singers _______ entirely satisfied with the acoustics of the renovated Brindley Theatre, which had been closed for seventeen months during construction.', $lyceon_json$[{"key":"A","text":"was"},{"key":"B","text":"were"},{"key":"C","text":"has been"},{"key":"D","text":"is being"}]$lyceon_json$::jsonb, 'B', NULL, E'When a ''neither...nor'' construction joins subjects, the verb agrees with the subject nearest to it. Here, the nearest subject is ''the three backup singers,'' which is plural, so the verb must be plural as well. ''Were'' is the correct plural past-tense form. ''Was'' is singular and would only be correct if the nearest subject were singular. ''Has been'' is singular present perfect, which disagrees in both number and tense. ''Is being'' is singular present progressive, which also disagrees in number and tense with the context.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2XMMPVU', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 2, 'mcq', E'Based on the passage, it can most reasonably be inferred that the European traders at Cacheu ________', E'Historian Amara Diallo has documented the surprisingly robust trade networks maintained by the kingdom of Kaabu in present-day Guinea-Bissau during the seventeenth century. Despite lacking navigable rivers connecting its interior capitals to the coast, Kaabu''s merchants developed an extensive system of dry-season footpaths and relay stations that enabled goods to travel from the inland city of Kansala to the coastal trading post of Cacheu in under nine days. Diallo notes that European traders stationed at Cacheu during this period consistently underestimated the volume of goods arriving from the interior, because they assumed that the absence of river transport would severely limit overland trade capacity.', $lyceon_json$[{"key":"A","text":"were unfamiliar with the dry-season footpath and relay station system that Kaabu's merchants used to transport goods overland."},{"key":"B","text":"deliberately underreported the volume of interior trade to their sponsors in order to negotiate more favorable contract terms."},{"key":"C","text":"had extensive firsthand experience navigating the inland trade routes between Kansala and the coast."},{"key":"D","text":"believed that maritime trade routes were less profitable than overland trade routes for transporting goods across the region."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage states that the European traders underestimated overland trade volume because they assumed the absence of river transport would severely limit it. This assumption implies they did not know about the footpath and relay station system that actually enabled high-volume overland trade. The claim about deliberate underreporting to sponsors introduces a motive the passage never suggests. The claim about firsthand experience navigating inland routes contradicts the implication that the traders were stationed at the coast and lacked knowledge of the interior system. The claim about maritime routes being less profitable than overland routes reverses the traders'' apparent assumption and addresses a comparison the passage never makes.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2YB9BEQ', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 3, 'mcq', E'A researcher wants to challenge Okonkwo''s conclusion. Which finding, if true, would most effectively undermine the argument presented in the passage?', E'Political scientist Rashida Okonkwo has argued that voter turnout in local elections correlates more strongly with the perceived accessibility of polling locations than with the intensity of campaign messaging. In a 2023 analysis of 217 municipal elections across four West African nations, Okonkwo found that turnout increased by an average of 11 percentage points in districts where new polling stations were opened within 2 kilometers of the population center, regardless of whether campaign spending in those districts rose or fell. By contrast, districts where campaign spending doubled but polling station locations remained unchanged showed turnout increases of only 2 to 3 percentage points.', $lyceon_json$[{"key":"A","text":"In the districts that received new polling stations, local civic organizations simultaneously launched door-to-door voter mobilization drives that had no parallel in districts without new stations."},{"key":"B","text":"Campaign spending in West African municipal elections is generally lower per voter than campaign spending in national elections within the same countries."},{"key":"C","text":"Several of the districts that received new polling stations also experienced population growth during the study period, which independently increased the number of registered voters."},{"key":"D","text":"Voters surveyed after the elections reported that they found the new polling stations more convenient than the previous ones, confirming that accessibility improvements were noticed by the electorate."}]$lyceon_json$::jsonb, 'A', NULL, E'Okonkwo''s argument depends on attributing the 11-point turnout increase to polling station accessibility rather than to other factors. The finding that civic organizations ran simultaneous mobilization drives only in the districts with new stations introduces a confounding variable that could explain the turnout increase, thereby undermining the causal link Okonkwo draws. The finding about lower per-voter campaign spending in municipal elections compared to national elections is irrelevant because Okonkwo''s analysis compares districts within municipal elections, not municipal elections to national ones. Population growth increasing registered voter counts would affect the total number of voters but not necessarily the turnout rate (percentage), and is thus a weaker challenge. The finding that voters found new stations more convenient actually supports Okonkwo''s claim rather than undermining it.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2ZS1FML', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 1, 'mcq', E'Which choice most logically completes the text?', E'The island of Socotra, located off the coast of Yemen, is home to over 300 plant species found nowhere else on Earth. ______, its dragon blood tree, named for its crimson sap, has become a symbol of the island''s extraordinary biodiversity.', $lyceon_json$[{"key":"A","text":"In particular,"},{"key":"B","text":"Nevertheless,"},{"key":"C","text":"As a result,"},{"key":"D","text":"In comparison,"}]$lyceon_json$::jsonb, 'A', NULL, E'The second sentence provides a specific example of the general claim made in the first sentence about Socotra''s unique plant life. "In particular" correctly signals that the dragon blood tree is being offered as a notable instance of the island''s endemic species. "Nevertheless" incorrectly introduces a contrast where none exists. "As a result" wrongly implies the tree''s symbolic status is a consequence of the island having unique species, when the sentence is illustrating the biodiversity, not describing an effect. "In comparison" suggests a comparison is being drawn, but no second entity is introduced for comparison.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2ZV7EZI', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 2, 'mcq', E'Which choice most logically completes the text?', E'Early mechanical clocks, first developed in European monasteries during the thirteenth century, relied on a verge-and-foliot escapement that was notoriously imprecise. These devices could drift by as much as fifteen minutes per day. ______, they served an important social function: by dividing the day into uniform hours, they began to shift communities away from the variable timekeeping practices tied to sunrise and sunset.', $lyceon_json$[{"key":"A","text":"Similarly,"},{"key":"B","text":"Consequently,"},{"key":"C","text":"Even so,"},{"key":"D","text":"For this reason,"}]$lyceon_json$::jsonb, 'C', NULL, E'The passage first establishes that early clocks were highly imprecise, then pivots to acknowledge that they nonetheless played a valuable social role. "Even so" correctly signals this concessive relationship: despite their inaccuracy, the clocks still mattered. "Similarly" implies a parallel between two comparable ideas, but the passage shifts from a drawback to a benefit, not from one similarity to another. "Consequently" and "For this reason" both indicate a cause-and-effect link, suggesting the social function resulted from the imprecision, which misrepresents the logical relationship in the passage.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
